let language='en';try{language=new URLSearchParams(location.search).get('lang')||localStorage.getItem('hanae-language')||'en'}catch{}if(!['en','ja'].includes(language))language='en';
const el=id=>document.getElementById(id),L=(en,ja)=>language==='ja'?ja:en;let scene='coffee',showTranslation=false,character='megumi',questionIndex=0,answers=[];
const scenes={coffee:['ONE COFFEE, PLEASE','コーヒーをひとつください。','Kōhī o hitotsu kudasai.','One coffee, please.','コーヒーを注文する'],store:['A BAG, PLEASE','袋をください。','Fukuro o kudasai.','A bag, please.','袋をお願いする'],school:['NICE TO MEET YOU','はじめまして。','Hajimemashite.','Nice to meet you.','初めてのあいさつ']};
function renderScene(){const s=scenes[scene];el('phrase-label').textContent=L(s[0],s[4]);el('japanese').textContent=s[1];el('romaji').textContent=s[2];el('translation').textContent=L(s[3],'英語では：'+s[3]);el('translation').hidden=!showTranslation;el('reveal').textContent=showTranslation?L('Hide meaning ↑','意味を閉じる ↑'):L('What does it mean? ↗','英語の意味を見る ↗');document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('active',b.dataset.scene===scene);b.setAttribute('aria-pressed',String(b.dataset.scene===scene))})}
document.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>{scene=b.dataset.scene;showTranslation=false;renderScene()}));el('reveal')?.addEventListener('click',()=>{showTranslation=!showTranslation;renderScene()});
const fans={megumi:['私は伏黒恵が好きです。','Watashi wa Fushiguro Megumi ga suki desu.','I like Megumi Fushiguro.'],rengoku:['私は煉獄杏寿郎が好きです。','Watashi wa Rengoku Kyōjurō ga suki desu.','I like Kyojuro Rengoku.'],vegeta:['私はベジータが好きです。','Watashi wa Bejīta ga suki desu.','I like Vegeta.'],other:['私の好きなキャラクターは＿＿です。','Watashi no suki na kyarakutā wa ___ desu.','My favourite character is ___.']};function renderFan(){const f=fans[character];el('fan-ja').textContent=f[0];el('fan-romaji').textContent=f[1];el('fan-en').textContent=L(f[2],'英語では：'+f[2]);document.querySelectorAll('[data-character]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.character===character)))}document.querySelectorAll('[data-character]').forEach(b=>b.addEventListener('click',()=>{character=b.dataset.character;renderFan()}));
function updateOrder(){const coffee=el('drink').value==='coffee',here=el('place').value==='here';el('order-ja').textContent=(coffee?'コーヒー':'紅茶')+'をひとつください。'+(here?'店内でお願いします。':'持ち帰りでお願いします。');el('order-romaji').textContent=(coffee?'Kōhī':'Kōcha')+' o hitotsu kudasai. '+(here?'Tennai':'Mochikaeri')+' de onegaishimasu.';el('order-en').textContent=L('','英語では：')+'One '+(coffee?'coffee':'black tea')+', please. '+(here?'For here, please.':'To take away, please.')}['drink','place'].forEach(id=>el(id)?.addEventListener('change',updateOrder));
const questions=[{en:'You didn’t catch what someone said. What could you say?',ja:'相手の言葉が聞き取れませんでした。何と言いますか？',a:['もう一度お願いします。','ありがとうございます。','おはようございます。'],correct:0,exEn:'Mō ichido onegaishimasu. — Once more, please.',exJa:'「もう一度お願いします。」と、繰り返してもらうように頼めます。'},{en:'You want a bag at the convenience store. Which phrase helps?',ja:'コンビニで袋が欲しいとき、何と言いますか？',a:['はじめまして。','袋をください。','いただきます。'],correct:1,exEn:'Fukuro o kudasai. — A bag, please.',exJa:'「袋をください。」とお願いします。'},{en:'You’re meeting another parent for the first time. How could you begin?',ja:'ほかの保護者と初めて会います。最初のあいさつは？',a:['お会計お願いします。','持ち帰りでお願いします。','はじめまして。'],correct:2,exEn:'Hajimemashite. — Nice to meet you.',exJa:'「はじめまして。」は初対面のあいさつです。'}];
function renderQuiz(){const score=answers.filter((a,i)=>a===questions[i].correct).length;el('quiz-score').textContent=L(score+' correct',score+'問正解');el('quiz-options').replaceChildren();if(questionIndex===3){el('quiz-progress').textContent=L('PRACTICE COMPLETE','練習完了');el('quiz-question').textContent=L('You tried three real-life moments. That’s a start worth making.','３つの場面を練習できました。小さな一歩が大切です。');el('quiz-feedback').textContent=L(score+' out of 3. Practise again whenever you like.','３問中'+score+'問正解。何度でも練習できます。');el('quiz-next').hidden=false;el('quiz-next').textContent=L('Try again ↻','もう一度挑戦 ↻');return}const q=questions[questionIndex],answered=answers[questionIndex]!==undefined;el('quiz-progress').textContent=L('QUESTION '+(questionIndex+1)+' OF 3','第'+(questionIndex+1)+'問 / 全３問');el('quiz-question').textContent=L(q.en,q.ja);el('quiz-feedback').textContent=answered?L((answers[questionIndex]===q.correct?'You’ve got it! ':'A useful one to practise: ')+q.exEn,(answers[questionIndex]===q.correct?'正解！ ':'一緒に覚えましょう。')+q.exJa):'';q.a.forEach((a,i)=>{const b=document.createElement('button');b.textContent=a;b.lang='ja';b.disabled=answered;if(answered&&i===q.correct)b.classList.add('correct');if(answered&&answers[questionIndex]===i&&i!==q.correct)b.classList.add('wrong');b.addEventListener('click',()=>{answers[questionIndex]=i;renderQuiz()});el('quiz-options').append(b)});el('quiz-next').hidden=!answered;el('quiz-next').textContent=questionIndex===2?L('See my result →','結果を見る →'):L('Next question →','次の問題へ →')}
el('quiz-next')?.addEventListener('click',()=>{if(questionIndex===3){questionIndex=0;answers=[]}else questionIndex++;renderQuiz()});
const dialog=el('booking');function updateBookingOptions(){
  const goal=el('goal').value;
  const isTrial=goal==='Beginner trial';
  const mode=el('mode');
  if(isTrial) mode.value='Online';
  mode.disabled=isTrial;
  el('trial-booking-note').hidden=!isTrial;
  el('kanji-booking-note').hidden=goal!=='Kanji & stories for my child';
}function openIntro(goal,mode){el('goal').value=goal||'Everyday life in Japan';el('mode').value=mode||'Online';el('intro').hidden=false;el('result').hidden=true;updateBookingOptions();dialog.showModal()}document.querySelectorAll('[data-meet]').forEach(b=>b.addEventListener('click',()=>openIntro(b.dataset.goal,b.dataset.mode)));el('goal').addEventListener('change',updateBookingOptions);el('close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});function renderResult(){const mode=el('mode').selectedOptions[0].textContent,goal=el('goal').selectedOptions[0].textContent;el('result').textContent=L('Your lesson options: '+mode+' · '+goal+'. This is a demo only. No enquiry has been sent and no booking has been made.','選んだレッスン：'+mode+'・'+goal+'。この画面はデモです。お問い合わせの送信や予約は行っていません。')}el('intro').addEventListener('submit',e=>{e.preventDefault();renderResult();el('result').hidden=false;el('intro').hidden=true});
function setLanguage(lang){language=lang;document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(node=>{const v=copy[node.dataset.i18n];if(v)node.innerHTML=v[lang]});document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.querySelector('nav').setAttribute('aria-label',L('Main navigation','メインナビゲーション'));if(document.querySelector('.portrait img'))document.querySelector('.portrait img').alt=L('Hanae smiling on a beach at sunset','夕暮れの海辺で笑顔のハナエ');document.title='ハナエと話しましょう — Hanae, let’s talk';document.querySelector('meta[name="description"]').content=L('Learn everyday Japanese online with Hanae. Start with a three-lesson trial for adult beginners, Monday to Friday.','ハナエとオンラインで学ぶ日常の日本語。大人の初心者向けに、月曜〜金曜の体験レッスン全３回をご用意。');if(el('phrase-label'))renderScene();if(el('fan-ja'))renderFan();if(el('drink'))updateOrder();if(el('quiz-options'))renderQuiz();if(el('kanji-symbol')&&typeof renderKanji==='function'&&kanjiReady)renderKanji();if(!el('result').hidden)renderResult();try{localStorage.setItem('hanae-language',lang);const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
// One-time scroll reveals; reduced motion keeps all content immediately visible.
if('IntersectionObserver' in window){const motion=matchMedia('(prefers-reduced-motion: reduce)');let observer;function setupReveals(){if(observer)observer.disconnect();document.querySelectorAll('.reveal-pending').forEach(n=>n.classList.remove('reveal-pending'));if(motion.matches)return;const targets=document.querySelectorAll('#services>.eyebrow,#services>.section-top,.service-card,.practice>div,.anime-intro,.anime-practice,.anime-bottom,.playground>h2,.playground .format-grid>article,.about>div,.faq>h2,.faq>details,.final-cta');observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');observer.unobserve(entry.target)}})},{threshold:.06,rootMargin:'0px 0px -24px 0px'});targets.forEach(n=>{n.classList.add('scroll-reveal');if(n.getBoundingClientRect().top>innerHeight){n.classList.add('reveal-pending');observer.observe(n)}})}setupReveals();motion.addEventListener('change',setupReveals);}


const kanjiSet=[{char:'川',en:'River',ja:'川',reading:'かわ (kawa)',word:'小川',exampleEn:'Stream — ogawa',exampleJa:'おがわ'},{char:'山',en:'Mountain',ja:'山',reading:'やま (yama)',word:'山',exampleEn:'Mountain — yama',exampleJa:'やま'},{char:'木',en:'Tree',ja:'木',reading:'き (ki)',word:'木',exampleEn:'Tree — ki',exampleJa:'き'},{char:'人',en:'Person',ja:'人',reading:'ひと (hito)',word:'人',exampleEn:'Person — hito',exampleJa:'ひと'}];let kanjiIndex=0,kanjiAnswer=null,kanjiReady=true;function renderKanji(){const k=kanjiSet[kanjiIndex];el('kanji-symbol').textContent=k.char;el('kanji-prompt').textContent=L('What does '+k.char+' mean?','「'+k.char+'」の意味は？');el('kanji-options').replaceChildren();kanjiSet.forEach((v,i)=>{const b=document.createElement('button');b.textContent=L(v.en,v.ja);b.disabled=kanjiAnswer!==null;if(kanjiAnswer!==null&&i===kanjiIndex)b.classList.add('correct');if(kanjiAnswer===i&&i!==kanjiIndex)b.classList.add('wrong');b.addEventListener('click',()=>{kanjiAnswer=i;renderKanji()});el('kanji-options').append(b)});el('kanji-feedback').textContent=kanjiAnswer===null?'':L((kanjiAnswer===kanjiIndex?'You’ve got it! ':'Let’s practise together. ')+k.char+' — '+k.en+'. One reading: '+k.reading+'. Example: '+k.word+' · '+k.exampleEn+'. Readings can change with the word.',(kanjiAnswer===kanjiIndex?'正解！ ':'一緒に覚えましょう。')+k.char+'：'+k.ja+'。読みの例：'+k.reading+'。言葉の例：'+k.word+'（'+k.exampleJa+'）。言葉によって読み方が変わります。');el('kanji-next').textContent=L('Try the next kanji →','次の漢字へ →');document.querySelectorAll('[data-kanji]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.kanji)===kanjiIndex)))}document.querySelectorAll('[data-kanji]').forEach(b=>b.addEventListener('click',()=>{kanjiIndex=Number(b.dataset.kanji);kanjiAnswer=null;renderKanji()}));el('kanji-next')?.addEventListener('click',()=>{kanjiIndex=(kanjiIndex+1)%kanjiSet.length;kanjiAnswer=null;renderKanji()});setLanguage(language);

// Use only Japanese voices: never fall back to an English pronunciation.
const audioEngine=('speechSynthesis' in window&&'SpeechSynthesisUtterance' in window)?window.speechSynthesis:null;const audioSlow={};let activeAudio=null,activeUtterance=null,audioToken=0;
function japaneseVoices(){if(!audioEngine)return [];return audioEngine.getVoices().filter(v=>/^ja(?:[-_]|$)/i.test(v.lang)).map((v,i)=>({v,i})).sort((a,b)=>voiceScore(b.v)-voiceScore(a.v)||a.i-b.i).map(x=>x.v)}function voiceScore(v){const name=v.name.toLowerCase();return (/natural|neural|premium/.test(name)?100:0)+(/enhanced|siri/.test(name)?70:0)+(/google/.test(name)?50:0)+(/kyoko|otoya|nanami|keita|haruka|ayumi|ichiro/.test(name)?35:0)-(/eddy|flo|grandma|grandpa|reed|rocko|sandy|shelley/.test(name)?30:0)+(v.default?5:0)}function japaneseVoice(){const voices=japaneseVoices();return voices.find(v=>/kyoko/i.test(v.name))||voices[0]||null}
function speechText(id){if(id==='phrase')return el('japanese').textContent;if(id==='fan')return {megumi:'わたしは、ふしぐろめぐみが好きです。',rengoku:'わたしは、れんごくきょうじゅろうが好きです。',vegeta:'わたしは、ベジータが好きです。',other:'わたしの好きなキャラクターは、なになにです。'}[character];if(id==='order')return el('order-ja').textContent;if(id==='kanji')return kanjiSet[kanjiIndex].reading.split(' ')[0];if(id==='example')return kanjiSet[kanjiIndex].exampleJa;if(id==='quiz'&&questionIndex<questions.length&&answers[questionIndex]!==undefined)return questions[questionIndex].a[questions[questionIndex].correct];return ''}
function audioStatus(id,text){const row=document.querySelector('[data-player="'+id+'"]');if(row)row.querySelector('.audio-status').textContent=text}
function updateAudioButtons(){document.querySelectorAll('[data-speech]').forEach(b=>{const playing=b.dataset.speech===activeAudio;b.setAttribute('aria-pressed',String(playing));const icon=b.querySelector('[aria-hidden]');if(icon)icon.textContent=playing?'■':'▶';b.classList.toggle('is-playing',playing);b.setAttribute('aria-label',playing?L('Stop audio','音声を停止'):b.textContent.replace('▶','').trim())});document.querySelectorAll('[data-slow]').forEach(b=>b.setAttribute('aria-pressed',String(!!audioSlow[b.dataset.slow])))}
let recordingPlayer;
function stopAudio(){audioToken++;if(recordingPlayer)recordingPlayer.pause();if(audioEngine)audioEngine.cancel();if(activeAudio)audioStatus(activeAudio,'');activeAudio=null;activeUtterance=null;updateAudioButtons()}
function playAudio(id){if(activeAudio===id){stopAudio();return}stopAudio();if(id==='kanji'&&kanjiSet[kanjiIndex].char==='川'){playRecording(id,kawaRecording);return}if((id==='kanji'||id==='example')&&kanjiSet[kanjiIndex].char==='木'){playRecording(id,kiRecording);return}if(id==='kanji'&&kanjiSet[kanjiIndex].char==='山'){playRecording(id,yamaRecording);return}if(!audioEngine){audioStatus(id,L('Audio is unavailable in this browser. Try Safari, Chrome or Edge with a Japanese speech voice enabled.','このブラウザーでは音声を利用できません。日本語の音声が使えるSafari、Chrome、Edgeなどでお試しください。'));return}const voice=japaneseVoice();if(!voice){audioStatus(id,L('No Japanese voice is available yet. Enable or download a Japanese speech voice in your device settings, then try again.','日本語の音声が見つかりません。端末の設定で日本語の読み上げ音声を有効にするかダウンロードしてから、もう一度お試しください。'));return}const text=speechText(id);if(!text)return;const token=++audioToken,utterance=new SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang='ja-JP';utterance.rate=audioSlow[id] ? 0.8 : 1.0;utterance.pitch=1;activeAudio=id;activeUtterance=utterance;audioStatus(id,L('Playing Japanese audio…','日本語の音声を再生中…'));updateAudioButtons();utterance.onend=()=>{if(token!==audioToken)return;audioStatus(id,L('Finished. Listen again whenever you like.','再生が終わりました。何度でも聞けます。'));activeAudio=null;activeUtterance=null;updateAudioButtons()};utterance.onerror=e=>{if(token!==audioToken)return;activeAudio=null;activeUtterance=null;audioStatus(id,L('Audio could not play. Check your device audio and Japanese voice settings, then try again.','再生できませんでした。端末の音量と日本語音声の設定を確認し、もう一度お試しください。'));updateAudioButtons()};try{audioEngine.speak(utterance)}catch{utterance.onerror()}}
document.querySelectorAll('[data-speech]').forEach(b=>b.addEventListener('click',()=>playAudio(b.dataset.speech)));document.querySelectorAll('[data-slow]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.slow;audioSlow[id]=!audioSlow[id];const wasPlaying=activeAudio===id;stopAudio();if(wasPlaying)playAudio(id);else updateAudioButtons()}));document.addEventListener('click',e=>{if(e.target.closest('[data-scene],[data-character],[data-kanji],#kanji-next,#quiz-next,#quiz-options,[data-lang]')){stopAudio();document.querySelectorAll('.audio-status').forEach(n=>n.textContent='');el('quiz-audio').hidden=questionIndex>=questions.length||answers[questionIndex]===undefined}});document.addEventListener('change',e=>{if(e.target.matches('#drink,#place'))stopAudio()});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});addEventListener('pagehide',stopAudio);if(audioEngine)audioEngine.addEventListener('voiceschanged',()=>{document.querySelectorAll('.audio-status').forEach(n=>{if(!activeAudio)n.textContent=''})});updateAudioButtons();


const kawaRecording='data:audio/mp4;base64,';
const kiRecording='data:audio/mp4;base64,';
function playRecording(id,source){
 const token=++audioToken;
 recordingPlayer=new Audio(source);
 recordingPlayer.currentTime=0;
 recordingPlayer.playbackRate=audioSlow[id]?0.8:1;
 activeAudio=id;
 audioStatus(id,L('Playing Hanae’s recording…','ハナエの音声を再生中…'));
 updateAudioButtons();
 function finish(message){
  if(token!==audioToken)return;
  activeAudio=null;
  audioStatus(id,message);
  updateAudioButtons();
 }
 const failed=()=>finish(L('Audio could not play. Please try again.','再生できませんでした。もう一度お試しください。'));
 recordingPlayer.onended=()=>finish(L('Finished.','再生が終わりました。'));
 recordingPlayer.onerror=failed;
 recordingPlayer.play().catch(failed);
}

const yamaRecording='data:audio/mp4;base64,';
